// Normalizer.java — brings data to 1NF by splitting repeating groups
package com.nbi.db;

import java.util.*;

public class Normalizer {
    public record Phone(String customerId, String phone) {}

    // 1NF: one atomic phone per row instead of a CSV blob.
    public List<Phone> toFirstNormalForm(RawCustomer c) {
        List<Phone> out = new ArrayList<>();
        for (String p : c.phonesCsv.split(",")) {
            out.add(new Phone(c.customerId, p.trim()));
        }
        return out;
    }
}
