public class AccountView {
    final String accountId;
    final String customerName; // duplicated from customers (denormalized)
    final String branchName;   // duplicated from branches (denormalized)
    final String branchCity;   // duplicated from branches (denormalized)

    public AccountView(String accountId, String customerName,
                       String branchName, String branchCity) {
        this.accountId = accountId;
        this.customerName = customerName;
        this.branchName = branchName;
        this.branchCity = branchCity;
    }
    public String toString() {
        return accountId + " | " + customerName + " | " + branchName + ", " + branchCity;
    }
}
