import java.util.*;

public class DenormalizedReadModel {
    private final Map<String, AccountView> views = new LinkedHashMap<>();

    // Precompute by "joining" normalized sources once, store flattened rows.
    public void rebuild(Map<String,String> acctToCustomer,
                        Map<String,String> customerName,
                        Map<String,String> acctToBranch,
                        Map<String,String[]> branchInfo) {
        for (String acct : acctToCustomer.keySet()) {
            String cust = acctToCustomer.get(acct);
            String[] br = branchInfo.get(acctToBranch.get(acct));
            views.put(acct, new AccountView(acct, customerName.get(cust), br[0], br[1]));
        }
