// Demo.java — shows 1NF split and the denormalized fast-read model
package com.nbi.db;

import java.util.*;

public class Demo {
    public static void main(String[] args) {
        // --- Normalization side: fix a 1NF violation ---
        RawCustomer raw = new RawCustomer("C1", "Rajesh Kumar", "9811, 9822, 9833");
        new Normalizer().toFirstNormalForm(raw)
            .forEach(p -> System.out.println("1NF phone row: " + p));

        // --- Denormalization side: flatten for fast dashboard reads ---
        var model = new DenormalizedReadModel();
        model.rebuild(
            Map.of("A100","C1","A200","C2"),                 // account -> customer
            Map.of("C1","Rajesh Kumar","C2","Sita Rao"),     // customer -> name
            Map.of("A100","BR01","A200","BR02"),             // account -> branch
            Map.of("BR01", new String[]{"Connaught Place","New Delhi"},
                   "BR02", new String[]{"Bandra","Mumbai"})  // branch -> {name,city}
        );
        System.out.println("Denormalized dashboard rows (no joins at read time):");
        model.all().forEach(v -> System.out.println("  " + v));
    }
}
